enemies=r/'assets/adventure/enemies.json';data=json.loads(enemies.read_text(encoding='utf-8'))
for row in [dict(id='sand_stalker',name=['Sand Stalker','Kum Avcısı'],health=50,attack=17,defense=1,speed=165,range=55,warning=350,cooldown=1000,xp=36,material='leather',quantity=2,weights=[['herb',3],['gold',1]]),dict(id='dune_scorpion',name=['Dune Scorpion','Kumul Akrebi'],health=80,attack=22,defense=8,speed=58,range=95,warning=1050,cooldown=2000,xp=42,material='desert_crystal',quantity=2,weights=[['herb',3],['iron',1]]),dict(id='ruin_sentinel',name=['Ruin Sentinel','Harabe Nöbetçisi'],health=88,attack=20,defense=5,speed=72,range=220,warning=900,cooldown=1500,xp=48,material='desert_crystal',quantity=2,weights=[['iron',2],['gold',1]])]:
 if not any(e['id']==row['id'] for e in data):data.append(row)
enemies.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
p=r/'assets/kingdom/recipes.json';data=json.loads(p.read_text(encoding='utf-8'))
if not any(e['id']=='crystal_tonic' for e in data):data.append(dict(id='crystal_tonic',name=['Crystal Purification Tonic','Kristal Arındırma İksiri'],description=['Restore 35 health and remove scorpion poison. Heal button uses it first in the desert.','35 can yeniler ve akrep zehrini temizler. Çölde İyileş önce bunu kullanır.'],cost={'desert_crystal':2,'herb':1,'gold':1},effects={'heal':35},category='consumable',level=22,ticks=4,building='forge'))
p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
p=r/'assets/kingdom/quests.json';data=json.loads(p.read_text(encoding='utf-8'))
if not any(e['id']=='main_22' for e in data):
 objectives=[]
 for key,en,tr,nav in [('entered','Enter the Ashen Desert','Kül Çölü’ne gir','desert'),('oasis','Discover the oasis','Vahayı keşfet','desert'),('kill','Defeat a desert enemy','Çöl düşmanını yen','desert'),('picked','Collect a regional crystal','Bölgeden kristal topla','desert'),('returned','Return safely with expedition proof','Sefer kanıtıyla güvenle dön','desert'),('registered','Register one real crystal at home','Evde gerçek bir kristali kaydet','desert_register')]:objectives.append(dict(kind='desert',key=key,target=1,text=[en,tr],navigate=nav))
 data.append(dict(id='main_22',level=22,chapter=5,title=['The Ashen Desert','Kül Çölü'],description=['The mine points beyond the hills. Find the oasis, face the desert and bring a crystal home to Arin.','Maden, tepelerin ötesini gösteriyor. Vahayı bul, çölle yüzleş ve Arin’e bir kristal getir.'],tracking='realm_lifetime',prerequisites=['main_21'],objectives=objectives,rewards={'xp':880,'gold':4,'wood':4,'stone':4},next=''))
p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Created original desert environment, three enemies, crystal/tonic and quest22 data')
